import './neon-card-header.scss';
import { dynamicText, createElement, updateDynamicText, createElementIf, dynamicAttr, updateDynamicAttributeOnChildren, updateConditionalElements, } from '../shared/dom-manipulation';
import { NeonWidgetSlotted } from '../shared/neon-widget-slotted';
import { stringHasCharacters } from '../shared/string-utils';
import { TooltipOnEllipsisObserver, tooltipOnEllipsis } from '../shared/extensions/tooltip-on-ellipsis';
export class NeonCardHeader extends NeonWidgetSlotted {
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return [
            'data-heading',
            'data-heading-type',
            'data-heading-url',
            'data-subheading',
            'data-color',
            'data-color-type',
            'data-background-image',
            'data-icon',
            'data-icon-size',
            'data-icon-stack-shape',
            'data-tag-text',
            'data-tag-subtext',
            'data-tag-icon',
            'data-tag-type',
            'data-show-avatar',
            'data-avatar-first-name',
            'data-avatar-last-name',
            'data-avatar-profile-picture-src',
            'data-avatar-background-option',
        ];
    }
    constructor() {
        super();
        this.widgetTag = 'neon-card-header';
        // If we ever have translated strings in this component then we should uncomment this.
        // i18nUnsubscribe?: () => void;
        this.isIdRequired = false;
        this.imageError = false;
        this.tooltipOnEllipsisObserver = new TooltipOnEllipsisObserver(this);
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            case 'data-heading':
                updateDynamicText(this);
                break;
            case 'data-heading-type':
                updateConditionalElements(this);
                break;
            case 'data-heading-url':
                updateDynamicAttributeOnChildren(this, 'href');
                break;
            case 'data-subheading':
                updateDynamicText(this);
                updateConditionalElements(this);
                break;
            case 'data-color':
                updateDynamicAttributeOnChildren(this, 'class');
                break;
            case 'data-color-type':
                updateDynamicAttributeOnChildren(this, 'class');
                updateDynamicAttributeOnChildren(this, 'data-color');
                break;
            case 'data-background-image':
                this.imageError = false;
                updateConditionalElements(this);
                updateDynamicAttributeOnChildren(this, 'src');
                break;
            case 'data-icon':
                if (newVal == null || oldVal == null) {
                    updateConditionalElements(this);
                }
                else {
                    updateDynamicAttributeOnChildren(this, 'data-icon');
                }
                updateDynamicAttributeOnChildren(this, 'class');
                break;
            case 'data-icon-size':
                updateDynamicAttributeOnChildren(this, 'data-size');
                updateDynamicAttributeOnChildren(this, 'class');
                break;
            case 'data-icon-stack-shape':
                updateConditionalElements(this);
                updateDynamicAttributeOnChildren(this, 'data-shape');
                updateDynamicAttributeOnChildren(this, 'class');
                break;
            case 'data-tag-text':
                if (newVal == null || oldVal == null) {
                    updateConditionalElements(this);
                }
                else {
                    updateDynamicAttributeOnChildren(this, 'data-text');
                }
                break;
            case 'data-tag-subtext':
                updateDynamicAttributeOnChildren(this, 'data-subtext');
                break;
            case 'data-tag-type':
                updateDynamicAttributeOnChildren(this, 'data-type');
                break;
            case 'data-tag-icon':
                updateDynamicAttributeOnChildren(this, 'data-icon');
                break;
            case 'data-show-avatar':
                updateConditionalElements(this);
                updateDynamicAttributeOnChildren(this, 'class');
                break;
            case 'data-avatar-first-name':
                updateConditionalElements(this);
                updateDynamicAttributeOnChildren(this, 'class');
                updateDynamicAttributeOnChildren(this, 'data-first-name');
                break;
            case 'data-avatar-last-name':
                updateConditionalElements(this);
                updateDynamicAttributeOnChildren(this, 'class');
                updateDynamicAttributeOnChildren(this, 'data-last-name');
                break;
            case 'data-avatar-profile-picture-src':
                updateConditionalElements(this);
                updateDynamicAttributeOnChildren(this, 'class');
                updateDynamicAttributeOnChildren(this, 'data-profile-picture-src');
                break;
            case 'data-avatar-background-option':
                updateConditionalElements(this);
                updateDynamicAttributeOnChildren(this, 'class');
                updateDynamicAttributeOnChildren(this, 'data-background-option');
                break;
            default:
        }
    }
    render() {
        return [
            createElementIf(() => {
                return !this.imageError && this.getAttribute('data-background-image') != null;
            }, 'div', {
                attrs: {
                    class: 'neon-card-header-background-image-container'
                }
            }, () => {
                return createElement('img', {
                    attrs: {
                        class: 'neon-card-header-background-image',
                        'src': dynamicAttr(() => {
                            return this.getAttribute('data-background-image');
                        })
                    },
                    properties: {
                        onerror: () => {
                            this.imageError = true;
                            updateConditionalElements(this);
                        }
                    }
                });
            }),
            createElement('div', {
                attrs: { class: 'neon-card-header-content' }
            }, createElement('div', { attrs: { class: 'neon-card-header-upper-row' } }, createElement('div', { attrs: { class: 'neon-card-header-heading-and-tag' } }, createElementIf(() => {
                return this.getIconType() === 'icon';
            }, 'neon-2_20_1-icon', {
                attrs: {
                    'data-icon': dynamicAttr(() => {
                        return this.getAttribute('data-icon');
                    }),
                    'data-size': dynamicAttr(() => {
                        return this.getAttribute('data-icon-size');
                    }),
                    'data-color': dynamicAttr(() => {
                        return this.getAttribute('data-color-type') === 'dark' ? 'white' : 'gray';
                    }),
                    'data-color-weight': '800'
                }
            }), createElementIf(() => {
                return this.getIconType() === 'icon-stack';
            }, 'neon-2_20_1-icon-stack', {
                attrs: {
                    'data-icon': dynamicAttr(() => {
                        return this.getAttribute('data-icon');
                    }),
                    'data-shape': dynamicAttr(() => {
                        return this.getAttribute('data-icon-stack-shape');
                    }),
                    'data-size': 'x-small'
                }
            }), createElementIf(() => {
                return this.getIconType() === 'avatar';
            }, 'neon-2_20_1-avatar', {
                attrs: {
                    'data-first-name': dynamicAttr(() => { return this.getAttribute('data-avatar-first-name'); }),
                    'data-last-name': dynamicAttr(() => { return this.getAttribute('data-avatar-last-name'); }),
                    'data-background-option': dynamicAttr(() => { return this.getAttribute('data-avatar-background-option'); }),
                    'data-profile-picture-src': dynamicAttr(() => { return this.getAttribute('data-avatar-profile-picture-src'); }),
                    'data-avatar-size': 'extra-small'
                }
            }), ...this.renderConditionalHeadingElements(), createElementIf(() => {
                return this.getAttribute('data-tag-text') != null;
            }, 'neon-2_20_1-tag', {
                attrs: {
                    'data-text': dynamicAttr(() => { return this.getAttribute('data-tag-text'); }),
                    'data-subtext': dynamicAttr(() => { return this.getAttribute('data-tag-subtext'); }),
                    'data-icon': dynamicAttr(() => { return this.getAttribute('data-tag-icon'); }),
                    'data-type': dynamicAttr(() => { return this.getAttribute('data-tag-type'); }),
                }
            })), this.getSlot('card-header-actions')), createElementIf(() => {
                return stringHasCharacters(this.getAttribute('data-subheading'));
            }, 'p', {
                attrs: {
                    class: dynamicAttr(() => {
                        return 'neon-card-header-subheading ' + this.getCardSubheadingIndentClass();
                    })
                },
                extensions: tooltipOnEllipsis,
                text: dynamicText(() => { return this.getAttribute('data-subheading'); })
            }))
        ];
    }
    /**
     * This function encapsulates the three types of headings that can come up with.
     * data-heading-type="text" > <h2><span>heading text</span></h2>
     * data-heading-type="link" > <h2><a>heading text</a></h2>
     * data-heading-type="link" > <button><h2>heading text</h2></button>
     */
    renderConditionalHeadingElements() {
        //We could have done a bit of this with a ternary inside a createElement,
        //but if we do that it ends up requiring redraws.
        return [
            createElementIf(() => {
                return this.getAttribute('data-heading-type') !== 'button';
            }, 'h2', {
                attrs: { class: 'neon-card-header-heading' }
            }, () => {
                return [
                    createElementIf(() => {
                        return this.getAttribute('data-heading-type') !== 'link';
                    }, 'span', {
                        attrs: {
                            class: 'neon-card-header-heading-text'
                        },
                        text: dynamicText(() => { return this.getAttribute('data-heading'); }),
                        extensions: tooltipOnEllipsis
                    }),
                    createElementIf(() => {
                        return this.getAttribute('data-heading-type') === 'link';
                    }, 'a', {
                        attrs: {
                            class: 'neon-card-header-heading-text neon-card-header-heading-clickable',
                            href: dynamicAttr(() => {
                                return this.getAttribute('data-heading-url');
                            })
                        },
                        listeners: {
                            click: () => {
                                this.dispatchEvent(new Event('neonCardHeaderHeadingClick'));
                            }
                        },
                        text: dynamicText(() => { return this.getAttribute('data-heading'); }),
                        extensions: tooltipOnEllipsis
                    })
                ];
            }),
            createElementIf(() => {
                return this.getAttribute('data-heading-type') === 'button';
            }, 'button', {
                attrs: {
                    class: 'neon-card-header-heading-clickable'
                },
                listeners: {
                    click: () => {
                        this.dispatchEvent(new Event('neonCardHeaderHeadingClick'));
                    }
                }
            }, () => {
                return [
                    createElement('h2', {
                        attrs: {
                            class: 'neon-card-header-heading neon-card-header-heading-text'
                        },
                        text: dynamicText(() => { return this.getAttribute('data-heading'); }),
                        extensions: tooltipOnEllipsis
                    })
                ];
            })
        ];
    }
    getCardSubheadingIndentClass() {
        switch (this.getSubheadingIndentSize()) {
            case 'x-small': return 'neon-card-header-subheading-intent-x-small';
            case 'small': return 'neon-card-header-subheading-intent-small';
            case 'medium': return 'neon-card-header-subheading-intent-medium';
            case 'large': return 'neon-card-header-subheading-intent-large';
            case 'x-large': return 'neon-card-header-subheading-intent-x-large';
            default:
                return '';
        }
    }
    getSubheadingIndentSize() {
        switch (this.getIconType()) {
            case 'icon':
                return this.getAttribute('data-icon-size') || 'medium';
            case 'icon-stack':
            case 'avatar':
                return 'medium';
            default:
        }
    }
    getIconType() {
        if (this.getAttribute('data-show-avatar') === 'true' ||
            stringHasCharacters(this.getAttribute('data-avatar-first-name')) ||
            stringHasCharacters(this.getAttribute('data-avatar-last-name')) ||
            stringHasCharacters(this.getAttribute('data-avatar-profile-picture-src')) ||
            stringHasCharacters(this.getAttribute('data-avatar-background-option'))) {
            return 'avatar';
        }
        if (this.getAttribute('data-icon') != null) {
            if (this.getAttribute('data-icon-stack-shape') != null) {
                return 'icon-stack';
            }
            return 'icon';
        }
    }
    connectedCallback() {
        this.tooltipOnEllipsisObserver.connect();
        super.connectedCallback();
        // If we ever have translated strings in this component then we should uncomment this.
        // this.i18nUnsubscribe = addTranslationListener(() => {
        //   updateDynamicText(this);
        // });
    }
    disconnectedCallback() {
        this.tooltipOnEllipsisObserver.disconnect();
        // If we ever have translated strings in this component then we should uncomment this.
        // if (this.i18nUnsubscribe != null) {
        //   this.i18nUnsubscribe();
        //   this.i18nUnsubscribe = undefined;
        // }
    }
}
